import { get } from 'lodash'

export function inputHandler (value, parentId, state) {
  const contextData = get(state, 'data', [])
  let newFormedData = [...contextData]
  newFormedData = newFormedData.map((item) => {
    if (item.id === parentId) {
      let lastItemIndex = ''
      if (item.tableData.length > 0) {
        const tableItemLength = item.tableData.length - 1
        const latTableItem = item.tableData[tableItemLength]
        lastItemIndex = latTableItem.id
      } else {
        lastItemIndex = 0
      }
      return {
        ...item,
        tableData: [...item.tableData, {
          id: lastItemIndex + 1,
          parent_id: item.provider_attribute_id,
          datatype: 'string',
          tableData: [],
          ...value
        }]
      }
    } else {
      return item
    }
  })
  return newFormedData
}