/* eslint-disable react-hooks/exhaustive-deps */
import { useEffect, useContext } from 'react'
import { Row, Col, Modal, Form, Input, Select, Button, notification } from 'antd'
import { useNewAttributeProvider, useResetState, useApiVersionList } from '../../hooks/useProviderDetails'
import get from 'lodash/get'
import { store } from '../../context/attributeContext'
const { Option } = Select

function AttributeModalAdd ({ ...props }) {
  const [{ addNewAttributesData, addNewAttributesStatus }, newAttributeAddRequest] = useNewAttributeProvider()
  const { form, provider, functionName, modalHandler, visible } = props
  const { validateFields, getFieldDecorator } = form
  const [{ apiVersionData, apiVersionStatus }, apiVersionListRequest] = useApiVersionList()
  const { dispatch } = useContext(store)
  const [resetProviderDetailsState] = useResetState()
  useEffect(() => {
    if (addNewAttributesStatus === 'success') {
      notification.success({
        message: get(addNewAttributesData, 'message')
      })
      if (provider && functionName) {
        apiVersionListRequest({
          query: {
            provider_code: provider,
            function_name: functionName,
            attributeType: 'payload'
          }
        })
      }
      resetProviderDetailsState(['addNewAttributesStatus', 'addNewAttributesData'])
    }
    if (addNewAttributesStatus !== 'success' && addNewAttributesStatus !== undefined) {
      notification.error({
        message: get(addNewAttributesData, 'message')
      })
      resetProviderDetailsState(['addNewAttributesStatus'])
    }
  }, [provider, addNewAttributesStatus])

  useEffect(() => {
    if (apiVersionStatus === 'success') {
      dispatch({
        type: 'provider-list-update',
        payload: get(apiVersionData, 'data.details.attributes', [])
      })
      resetProviderDetailsState(['apiVersionStatus'])
      modalHandler()
    } else {
      resetProviderDetailsState(['apiVersionStatus'])
      modalHandler()
    }
  }, [apiVersionStatus])

  const buttonSubmit = (e) => {
    e.preventDefault()
    validateFields((err, values) => {
      if (!err) {
        newAttributeAddRequest({
          query: {
            provider_code: provider,
            function_name: functionName
          },
          body: [values]
        })
      }
    })
  }
  const closeModalHandler = () => {
    modalHandler()
  }
  return (
    <Modal
      title='Add Provider attribute'
      visible={visible}
      footer={null}
      // onOk={this.handleOk}
      onCancel={closeModalHandler}
    >
      <Form onSubmit={buttonSubmit}>
        <Row type='flex' justify='center'>
          <Col span={10}>
            <Form.Item label='Field Code'>
              {
                getFieldDecorator('code', {
                  rules: [
                    {
                      required: true,
                      message: 'Field Code required'
                    }
                  ]
                })(<Input />)
              }
            </Form.Item>
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={10}>
            <Form.Item label='Field Name'>
              {
                getFieldDecorator('name', {
                  rules: [
                    {
                      required: true,
                      message: 'Field Name required'
                    }
                  ]
                })(<Input />)
              }
            </Form.Item>
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={10}>
            <Form.Item label='Datatype'>
              {
                getFieldDecorator('datatype', {
                  rules: [
                    {
                      required: true,
                      message: 'Field Datatype required'
                    }
                  ]
                })(
                  <Select
                    showSearch
                  >
                    <Option value='object'>Object</Option>
                    <Option value='string'>String</Option>
                    <Option value='int'>Int</Option>
                    <Option value='float64'>Float64</Option>
                    <Option value='date'>Date</Option>
                    <Option value='datetime'>DateTime</Option>
                  </Select>
                )
              }
            </Form.Item>
          </Col>
        </Row>
        <Row style={{ marginTop: 30 }} type='flex' justify='center'>
          <Col style={{ display: 'flex', justifyContent: 'center' }} span={10}>
            <Button type='default' onClick={closeModalHandler}>Cancel</Button>
          </Col>
          <Col style={{ display: 'flex', justifyContent: 'center' }} span={10}>
            <Button type='primary' htmlType='submit'>Submit</Button>
          </Col>
        </Row>
      </Form>
    </Modal>
  )
}
const WrappedModalComponent = Form.create()(AttributeModalAdd)

export default WrappedModalComponent
