import productConfigUrls from '../../../../../../../request/urls/productConfig'

const actions = {
  RESET_PROVIDER_DETAILS: 'RESET_PROVIDER_DETAILS',
  PROVIDER_LIST_REQUEST: 'PROVIDER_LIST_REQUEST',
  PROVIDER_LIST: 'PROVIDER_LIST',
  API_VERSION_REQUEST: 'API_VERSION_REQUEST',
  API_VERSION: 'API_VERSION',
  PROVIDER_CREDENTIAL_REQUEST: 'PROVIDER_CREDENTIAL_REQUEST',
  PROVIDER_CREDENTIAL: 'PROVIDER_CREDENTIAL',
  ADD_NEW_ATTRIBUTES_REQUEST: 'ADD_NEW_ATTRIBUTES_REQUEST',
  ADD_NEW_ATTRIBUTES: 'ADD_NEW_ATTRIBUTES',
  ADD_PROVIDER_ATTRIBUTES_REQUEST: 'ADD_PROVIDER_ATTRIBUTES_REQUEST',
  ADD_PROVIDER_ATTRIBUTES: 'ADD_PROVIDER_ATTRIBUTES',
  PROVIDER_ATTRIBUTES_REQUEST: 'PROVIDER_ATTRIBUTES_REQUEST',
  PROVIDER_ATTRIBUTES: 'PROVIDER_ATTRIBUTES',
  API_CREDENTIAL_VALUE_REQUEST: 'API_CREDENTIAL_VALUE_REQUEST',
  API_CREDENTIAL_VALUE: 'API_CREDENTIAL_VALUE',
  ACTIVE_VERSION_REQUEST: 'ACTIVE_VERSION_REQUEST',
  ACTIVE_VERSION: 'ACTIVE_VERSION',
  DATA_MAPPING_REQUEST: 'DATA_MAPPING_REQUEST',
  DATA_MAPPING: 'DATA_MAPPING',
  resetState: (fields = []) => ({
    type: actions.RESET_PROVIDER_DETAILS,
    payload: fields
  }),
  providerList: () => {
    return {
      type: actions.PROVIDER_LIST_REQUEST,
      payload: {
        method: 'authGet',
        url: productConfigUrls.getAllProductProvidersUrl
      }
    }
  },
  apiVersionList: (payload) => {
    return {
      type: actions.API_VERSION_REQUEST,
      payload: {
        ...payload,
        method: 'authGet',
        url: productConfigUrls.getVersionAPIUrl
      }
    }
  },
  providerCredentialPostData: (payload) => {
    return {
      type: actions.PROVIDER_CREDENTIAL_REQUEST,
      payload: {
        ...payload,
        method: 'authPost',
        url: productConfigUrls.apiCredentialRequestUrl
      }
    }
  },
  addNewAttributes: (payload) => {
    return {
      type: actions.ADD_NEW_ATTRIBUTES_REQUEST,
      payload: {
        ...payload,
        method: 'authPost',
        url: productConfigUrls.addNewAttributesProviderUrl
      }
    }
  },
  addProviderAttributes: (payload) => {
    return {
      type: actions.ADD_PROVIDER_ATTRIBUTES_REQUEST,
      payload: {
        ...payload,
        method: 'authPost',
        url: productConfigUrls.addProviderAttributesUrl
      }
    }
  },
  getProviderAttributes: (payload) => {
    return {
      type: actions.PROVIDER_ATTRIBUTES_REQUEST,
      payload: {
        ...payload,
        method: 'authGet',
        url: productConfigUrls.getProviderAttributesUrl
      }
    }
  },
  getApiCredentialValue: (payload) => {
    return {
      type: actions.API_CREDENTIAL_VALUE_REQUEST,
      payload: {
        ...payload,
        method: 'authGet',
        url: productConfigUrls.getApiCredentialDataUrl
      }
    }
  },
  getActiveVersion: (payload) => {
    return {
      type: actions.ACTIVE_VERSION_REQUEST,
      payload: {
        ...payload,
        method: 'authGet',
        url: productConfigUrls.getCurrentVersionUrl
      }
    }
  },
  getDataMapping: (payload) => {
    return {
      type: actions.DATA_MAPPING_REQUEST,
      payload: {
        ...payload,
        method: 'authGet',
        url: productConfigUrls.getConfigurableProductDetailattributeUrl
      }
    }
  }
}

export default actions
