import { mapArrayElementsKeysToObjectKeys } from '../../../../../../../helpers/utility'
import actions from './actions'

const INITIAL_STATE = {}

const providerDetailReducer = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case actions.RESET_PROVIDER_DETAILS: {
      const stateToBeReset = mapArrayElementsKeysToObjectKeys(payload)
      return { ...state, ...stateToBeReset }
    }
    case actions.PROVIDER_LIST:
      return { ...state, ...payload }
    case actions.API_VERSION:
      return { ...state, ...payload }
    case actions.PROVIDER_CREDENTIAL:
      return { ...state, ...payload }
    case actions.ADD_NEW_ATTRIBUTES:
      return { ...state, ...payload }
    case actions.ADD_PROVIDER_ATTRIBUTES:
      return { ...state, ...payload }
    case actions.PROVIDER_ATTRIBUTES:
      return { ...state, ...payload }
    case actions.API_CREDENTIAL_VALUE:
      return { ...state, ...payload }
    case actions.ACTIVE_VERSION:
      return { ...state, ...payload }
    case actions.DATA_MAPPING:
      return { ...state, ...payload }
    default:
      return state
  }
}

export { INITIAL_STATE }
export default providerDetailReducer
