/* eslint-disable react-hooks/exhaustive-deps */
import { useState, useEffect, useContext } from 'react'
import { Row, Col, Table, Button, notification } from 'antd'
import { get } from 'lodash'
import { store } from '../../context/attributeContext'
import { TableColumns } from '../../constants/providerTable'
import AttributeModal from './NormalAttributeAdd'
import { tableMapper } from './tableDataMapper'
import { useResetState, useAddProviderAttributes } from '../../hooks/useProviderDetails'
import { payloadFormation } from '../../commanFunction/payloadFormation'
import { useLoaderContextValue } from '../../../../../../../../../globalContextProvider/LoaderContext'
export default function TreeFieldData ({ ...props }) {
  const { type = 'add', step2 = [], screenChange, history, tableData = [], parentId = '', provider, productCode, packageCode } = props
  const { state } = useContext(store)
  const [buttonDisbaleState, setButtonDisabled] = useState(true)
  const [tableDataState, setTableData] = useState([])
  const [attributeModalvisible, setAttributeModalVisible] = useState(false)
  const [{ addProviderAttributesData, addProviderAttributesStatus }, attributeAddRequest] = useAddProviderAttributes()
  const [{ ADD_PROVIDER_ATTRIBUTES }] = useLoaderContextValue()
  const [resetProviderDetailsState] = useResetState()

  useEffect(() => {
    if (type === 'add') {
      if (addProviderAttributesStatus === 'success') {
        notification.success({
          message: get(addProviderAttributesData, 'message')
        })
        resetProviderDetailsState(['addProviderAttributesStatus', 'addProviderAttributesData'])
      }
      if (addProviderAttributesStatus !== 'success' && addProviderAttributesStatus !== undefined) {
        notification.error({
          message: get(addProviderAttributesData, 'data.message')
        })
        resetProviderDetailsState(['addProviderAttributesStatus', 'addProviderAttributesData'])
      }
    }
  }, [addProviderAttributesData])

  useEffect(() => {
    const tableSourceData = tableMapper(tableData, type)
    setTableData(tableSourceData)
  }, [tableData])

  useEffect(() => {
    if (type === 'add') {
      const payload = JSON.parse(window.sessionStorage.getItem('attributeData')) || []
      const tableSourceData = payload
      setTableData(tableSourceData)
    }
  }, [])

  useEffect(() => {
    const functionName = get(state, 'functionName')
    if (buttonDisbaleState && functionName) {
      setButtonDisabled(false)
    }
  }, [state])

  const screenChanger = () => {
    if (type === 'add') {
      screenChange('screen2')
    } else {
      setAttributeModalVisible(true)
    }
  }

  const closeModalHandler = () => {
    setAttributeModalVisible(false)
  }

  const routeToDetailPage = (data) => {
    const functionName = get(state, 'functionName')
    history.push({
      pathname: '/product-config/create-product/3/provider-attribute-form',
      state: {
        functionName,
        providerAttributeData: data,
        provider,
        productCode,
        packageCode,
        step2
      }
    })
  }
  const routeToDetailPageNewField = () => {
    if (type === 'edit') {
      const functionName = get(state, 'functionName')
      history.push({
        pathname: '/product-config/create-product/3/provider-attribute-form',
        state: {
          functionName,
          providerAttributeData: [],
          provider,
          productCode,
          packageCode,
          step2
        }
      })
    }
  }
  const onSubmitDataHandler = () => {
    const payload = payloadFormation(tableDataState)
    attributeAddRequest({
      query: {
        provider_code: provider,
        function_name: get(state, 'functionName'),
        product_code: productCode,
        package_code: packageCode
      },
      body: payload
    })
  }
  return (
    <>
      <AttributeModal
        provider={provider}
        functionName={get(state, 'functionName')}
        visible={attributeModalvisible}
        parentId={parentId}
        closeModal={closeModalHandler}
      />
      <Row type='flex' justify='end'>
        {
          (type === 'add' || type === 'modal') &&
            <Col>
              <Button disabled={buttonDisbaleState} type='primary' onClick={screenChanger}>Add Field</Button>
            </Col>
        }
        {
          (type === 'edit') &&
            <Col>
              <Button type='primary' onClick={routeToDetailPageNewField}>Add New Field</Button>
            </Col>
        }
      </Row>
      <Row type='flex' justify='center'>
        <Col span={24}>
          <Table
            columns={TableColumns.call(this, { routeToDetailPage, step2, providerList: get(state, 'providerList'), type })}
            dataSource={tableDataState}
          />
        </Col>
        {
          type === 'add' &&
            <Col span={10}>
              <Button loading={ADD_PROVIDER_ATTRIBUTES} disabled={tableDataState.length === 0} type='primary' onClick={onSubmitDataHandler}>Submit</Button>
            </Col>
        }
      </Row>
    </>
  )
}
