
import { get } from 'lodash'
export function TableColumns (props) {
  const { type } = props
  const handleRoute = (record) => {
    props.routeToDetailPage(record)
  }
  const columns = [{
    title: 'Field Key',
    dataIndex: 'provider_attribute_id',
    key: 'provider_attribute_id',
    render: (_, record) => {
      const { providerList = [] } = props
      const providerItem = providerList.length > 0 ? providerList.find((item) => item.id === record.provider_attribute_id) : {}
      return type === 'edit' ? record.attribute_name : get(providerItem, 'name', '')
    }
  },
  {
    title: 'Data Mapping',
    dataIndex: 'product_attribute_id',
    key: 'product_attribute_id',
    render: (_, record) => {
      const { step2 = [] } = props
      const attributeItem = step2.length > 0 ? step2.find((item) => item.id === record.product_attribute_id) : {}
      return get(attributeItem, 'name', '')
    }
  },
  {
    title: 'Prefix',
    dataIndex: 'prefix',
    key: 'prefix'
  },
  {
    title: 'Suffix',
    dataIndex: 'suffix',
    key: 'suffix'
  },
  {
    title: 'Formatting',
    dataIndex: 'formatting',
    key: 'formatting'
  },
  {
    title: 'To String',
    dataIndex: 'convert_value_to_string',
    key: 'convert_value_to_string',
    render: (_, record) => {
      return record.convert_value_to_string ? 'True' : 'False'
    }
  },
  {
    title: 'In Array',
    dataIndex: 'is_array',
    key: 'is_array',
    render: (_, record) => {
      return record.is_array ? 'True' : 'False'
    }
  },
  {
    title: 'DataType',
    dataIndex: 'datatype',
    key: 'datatype'
  }]
  if (type === 'edit') {
    columns.push({
      title: 'Action',
      fixed: 'right',
      width: 100,
      render: (data, record) => {
        if (record) {
          return (<span className='anchor' onClick={() => handleRoute(record)}>Edit</span>)
        }
      }
    })
  }
  return columns
}
