export function tableMapper (tableData, type = '') {
  function traverse (data, parentKey = '') {
    return data.map((item, index) => {
      const key = parentKey ? +`${parentKey}${index + 1}` : index + 1
      const data = {
        key: key,
        attribute_name: (type === 'edit') ? item.attribute_name : '',
        provider_attribute_id: item.provider_attribute_id,
        parent_id: item.parent_id,
        product_attribute_id: item.product_attribute_id,
        is_array: item.is_array,
        datatype: item.datatype,
        prefix: item.prefix,
        suffix: item.suffix,
        convert_value_to_string: item.convert_value_to_string,
        formatting: item.formatting,
        children: (item.nested && item.nested.length > 0) ? traverse(item.nested, key) : false,
        fallback_product_attribute_id: item.fallback_product_attribute_id,
        fallback_type: item.fallback_type,
        fallback_static_value: item.fallback_static_value,
        status: item.status,
        convert_value_to_numeric: item.convert_value_to_numeric
      }
      return data
    })
  }
  return traverse(tableData)
}

export function sessionTableMapper (data) {
  if (data.length === 0) {
    return data.map((item) => {
      return {
        ...item,
        children: false
      }
    })
  } else {
    let parentData = data[0]
    data.shift()
    const childData = traverseChild(data)
    parentData = [{
      ...parentData,
      tableData: [...childData],
      children: childData.length > 0 ? [...childData] : false
    }]
    return parentData
  }
}

export function traverseChild (data) {
  function traverse (data) {
    return data.map((item) => {
      return {
        ...item,
        children: item.tableData.length > 0 ? traverse(item.tableData) : false
      }
    })
  }

  return traverse(data)
}
