import { useContext, useState } from 'react'
import { Row, Col, Modal, Select, Divider, Icon, Input, Checkbox, Button, Form } from 'antd'
import { store } from '../../context/attributeContext'
import { inputHandler } from './inputHandler'
import { get } from 'lodash'
import AddAttributeModal from '../AttributeField/NewAttributeAddModal'

const { Option } = Select
function NormalAttributeAddModal ({ ...props }) {
  const { provider, functionName, visible, parentId, closeModal, stateData, form } = props
  const { state, dispatch } = useContext(store)
  const providerListState = get(state, 'providerList', []).filter(item => item.type !== 'object')
  const attributeListState = get(state, 'attributesList')
  const { getFieldDecorator, validateFields, resetFields, getFieldValue } = form
  const fallbackType = getFieldValue('fallback_type')
  const [modalVisible, setModalVisible] = useState(false)
  const fallbackTypeList = ["static", "derived"]
  const handleSubmit = (e) => {
    e.preventDefault()
    validateFields((err, values) => {
      if (!err) {
        const data = inputHandler(values, parentId, state)
        dispatch({
          type: 'update-data',
          payload: data
        })
        resetFields()
        closeModal()
      }
    })
  }
  const modalVisibleHandler = () => {
    setModalVisible(false)
  }
  return (
    <Modal
      closable
      title='Attribute Add'
      visible={visible}
      footer={null}
      width={800}
      onCancel={closeModal}
    >
      <AddAttributeModal
        visible={modalVisible}
        functionName={functionName}
        provider={provider}
        modalHandler={modalVisibleHandler}
      />
      <Form onSubmit={handleSubmit}>
        <Row type='flex' justify='center'>
          <Col style={{ padding: '20px 40px' }} span={22}>
            <Row type='flex' justify='space-between' align='middle'>
              <Col className='field__section' span={10}>
                <Form.Item label='Field Key'>
                  {
                    getFieldDecorator('provider_attribute_id', {
                      rules: [{
                        required: true,
                        message: 'Provider Attribute Id Required'
                      }]
                    })(
                      <Select
                        showSearch
                        filterOption={
                            (input, option) => option.props.searchValue.toLowerCase().indexOf(input.toLowerCase()) >= 0
                        }
                        dropdownRender={menu => (
                          <div>
                            {menu}
                            <Divider style={{ margin: '4px 0' }} />
                            <div
                              style={{ padding: '4px 8px', cursor: 'pointer' }}
                              onMouseDown={e => e.preventDefault()}
                              onClick={() => setModalVisible(true)}
                            >
                              <Icon type='plus' /> Add item
                            </div>
                          </div>
                        )}
                      >
                        {providerListState.map((item, index) => (<Option key={index} value={item.id} searchValue={item.name}>{item.name}</Option>))}
                      </Select>)
                  }
                </Form.Item>
              </Col>
              <Col className='field__section' span={10}>
                <Form.Item label='Data Mapping'>
                  {
                    getFieldDecorator('product_attribute_id', {
                      rules: [{
                        required: false,
                        message: 'Product Attribute Id Required'
                      }]
                    })(
                      <Select 
                      showSearch 
                      allowClear 
                      filterOption={
                        (input, option) =>
                          option.props.searchValue.toLowerCase().indexOf(input.toLowerCase()) >= 0
                      }>
                        {attributeListState.map((item, index) => (<Option key={index} value={item.id} searchValue={item.name}>{item.name} <b>({item.attribute_type})</b></Option>))}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
              <Col className='field__section' span={10}>
                <Form.Item label='Prefix'>
                  {
                    getFieldDecorator('prefix', {
                      rules: [{
                        required: false,
                        message: 'Field Required'
                      }]
                    })(<Input />)
                  }
                </Form.Item>
              </Col>
              <Col className='field__section' span={10}>
                <Form.Item label='Suffix'>
                  {
                    getFieldDecorator('suffix', {
                      rules: [{
                        required: false,
                        message: 'Field Required'
                      }]
                    })(<Input />)
                  }
                </Form.Item>
              </Col>
              <Col className='field__section' span={10}>
                <Form.Item label='Formatting'>
                  {
                    getFieldDecorator('formatting', {
                      rules: [{
                        required: false,
                        message: 'Field Required'
                      }]
                    })(<Input />)
                  }
                </Form.Item>
              </Col>
              <Col className='field__section' span={10}>
                <Form.Item label='Fallback Type'>
                  {
                    getFieldDecorator('fallback_type', {
                      rules: []
                    })(
                      <Select 
                      showSearch 
                      allowClear 
                      filterOption={
                        (input, option) =>
                          option.props.searchValue.toLowerCase().indexOf(input.toLowerCase()) >= 0
                      }>
                        {fallbackTypeList.map((item, index) => (<Option key={index} value={item} searchValue={item.name}>{item}</Option>))}
                      </Select>
                    )
                  }
                </Form.Item>
              </Col>
              <Col className='field__section' span={10}>
                {fallbackType == "static" && <Form.Item label='Fallback Static Value'>
                  {
                    getFieldDecorator('fallback_static_value', {
                      rules: [{
                        required: false,
                        message: 'Field Required'
                      }]
                    })(<Input />)
                  }
                </Form.Item>}
                {fallbackType == "derived" && <Form.Item label='FallBack Data Mapping'>
                  {
                    getFieldDecorator('fallback_product_attribute_id', {
                      rules: []
                    })(
                      <Select 
                      showSearch 
                      allowClear 
                      filterOption={
                        (input, option) =>
                          option.props.searchValue.toLowerCase().indexOf(input.toLowerCase()) >= 0
                      }>
                        {attributeListState.map((item, index) => (<Option key={index} value={item.id} searchValue={item.name}>{item.name} <b>({item.attribute_type})</b></Option>))}
                      </Select>
                    )
                  }
                </Form.Item>}
              </Col>
              <Col className='field__section' span={10}>
                <div className='checkbox__section' style={{ width: 'max-content' }}>
                  <Form.Item style={{marginBottom: 0 }}>
                    {
                      getFieldDecorator('convert_value_to_string', {
                        valuePropName: 'checked',
                        rules: [{
                          required: false,
                          message: 'Field Required'
                        }],
                        initialValue: false
                      })(<Checkbox>convert to string in the payload</Checkbox>)
                    }
                  </Form.Item>
                  <Form.Item style={{marginBottom: 0 }}>
                    {
                      getFieldDecorator('convert_value_to_numeric', {
                        valuePropName: 'checked',
                        rules: [{
                          required: false,
                          message: 'Field Required'
                        }],
                        initialValue: false
                      })(<Checkbox>convert to numeric in the payload</Checkbox>)
                    }
                  </Form.Item>
                  <Form.Item>
                    {
                      getFieldDecorator('is_array', {
                        valuePropName: 'checked',
                        rules: [{
                          required: false,
                          message: 'Field Required'
                        }],
                        initialValue: false
                      })(<Checkbox>value is array</Checkbox>)
                    }
                  </Form.Item>
                </div>
              </Col>
            </Row>
          </Col>
        </Row>
        <Row type='flex' justify='center'>
          <Col span={20}>
            <div style={{ display: 'flex', justifyContent: 'space-between' , width: '100%' }}>
              <Button type='default' onClick={closeModal}>Cancel</Button>
              <Button type='primary' htmlType='submit'>Submit</Button>
            </div>
          </Col>
        </Row>
      </Form>
    </Modal>
  )
}

const WrappedFormComponent = Form.create()(NormalAttributeAddModal)

export default WrappedFormComponent
