export function payloadFormation (data) {
  const newData = []
  function traverse (data) {
    data.forEach((item) => {
      const data = {
        provider_attribute_id: item.provider_attribute_id,
        parent_id: item.parent_id,
        product_attribute_id: item.product_attribute_id,
        is_array: item.is_array,
        prefix: item.prefix,
        suffix: item.suffix,
        convert_value_to_string: item.convert_value_to_string,
        formatting: item.formatting,
        fallback_product_attribute_id: item.fallback_product_attribute_id,
        fallback_type: item.fallback_type,
        status: item.status,
        convert_value_to_numeric: item.convert_value_to_numeric,
        fallback_static_value: item.fallback_static_value
      }
      newData.push(data)
      if (item.tableData && item.tableData.length > 0) {
        traverse(item.tableData)
      }
    })
  }
  traverse(data)
  return newData
}
