import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../reducer'

export const ProviderDetailContext = createContext()

export const ProviderDetailContextProvider = (props) => {
  return (
    <ProviderDetailContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </ProviderDetailContext.Provider>
  )
}

export const useProviderDetailContextValue = () => useContext(ProviderDetailContext)
