import React, { createContext, useReducer } from 'react'

const initialState = {
  showCollapsePanel: ['1'],
  functionName: '',
  attributesList: [],
  providerList: [],
  apiVersionDynamicData: [],
  normalMapping: {
    id: 1,
    datatype: '',
    fieldType: 'enabled',
    buttonType: 'regular',
    provider_attribute_id: null,
    parent_id: null,
    product_attribute_id: null,
    is_array: false,
    prefix: '',
    suffix: '',
    convert_value_to_string: false,
    fallback_product_attribute_id: null,
    fallback_type: null,
    status: 'active',
    convert_value_to_numeric: false,
    fallback_static_value: '',
    formatting: '',
    showAddButton: false,
    showDeleteButton: false,
    tableShow: false,
    tableData: []
  },
  data: [{
    id: 1,
    datatype: '',
    fieldType: 'enabled',
    provider_attribute_id: null,
    buttonType: 'regular',
    parent_id: null,
    product_attribute_id: null,
    is_array: false,
    prefix: '',
    suffix: '',
    status: 'active',
    convert_value_to_numeric: false,
    fallback_product_attribute_id: null,
    fallback_type: null,
    fallback_static_value: '',
    convert_value_to_string: false,
    formatting: '',
    showAddButton: false,
    showDeleteButton: false,
    tableShow: false,
    tableData: []
  }]
}

const store = createContext(initialState)
const { Provider } = store

const StateProvider = ({ children }) => {
  const [state, dispatch] = useReducer((state, action) => {
    switch (action.type) {
      case 'provider-list-update':
        return {
          ...state,
          providerList: action.payload
        }
      case 'attribute-list-update':
        return {
          ...state,
          attributesList: action.payload
        }
      case 'set-function-name':
        return {
          ...state,
          functionName: action.payload
        }
      case 'update-data':
        return {
          ...state,
          data: action.payload
        }
      case 'update-collapse':
        return {
          ...state,
          showCollapsePanel: action.payload
        }
      case 'update-api-version-data':
        return {
          ...state,
          apiVersionDynamicData: action.payload
        }
      default:
        throw new Error()
    }
  }, initialState)

  return <Provider value={{ state, dispatch }}>{children}</Provider>
}

export { store, StateProvider }
