import { useProviderDetailContextValue } from '../context'
import useServiceRequest from '../../../../../../../../hooks/useServiceRequest'
import actions from '../actions'

export function useResetState () {
  const [, dispatch] = useProviderDetailContextValue()
  const resetProviderDetailsState = async (keys = []) => {
    await dispatch(actions.resetState(keys))
  }
  return [resetProviderDetailsState]
}

export function useProviderList () {
  const [{ providerListData, providerListStatus }, dispatch] = useProviderDetailContextValue()

  const [callApi] = useServiceRequest(dispatch)
  const request = async (payload = {}) => {
    await callApi(actions.providerList(payload))
  }
  return [{ providerListData, providerListStatus }, request]
}

